'use client'
import {AlertTriangle,ExternalLink,Film,Link2,PackageCheck,ShieldCheck} from 'lucide-react'

export type SourceShot={id:string;order:number;startSec:number|null;endSec:number|null;[field:string]:unknown}
export type CreativeSource={brandId:string;creativeId:string;inspirationCreativeId?:string|null;title?:string|null;platform?:string|null;sourceRevision?:string|null;sourceDigest?:string|null;libraryDigest?:string|null;evidenceStatus:string;internalDetailPath:string;originalVideoUrl:string|null;originalPostUrl:string|null;sourceEvidence:{originalText:string};timeline:SourceShot[]}
export type SourcePreservation={hookRole?:'preserved'|'adapted'|'not_applicable';narrativeRole?:'preserved'|'adapted';pacingRole?:'preserved'|'adapted';changeReasons?:string[]}
export type FidelityDimension={key:string;status:'passed'|'failed'|'not_applicable';issues:string[];sourceShotIds?:string[]}
export type SourceComparisonShot={id:string;title?:string;prompt:string;clipUrl?:string|null;spokenText?:string|null;overlayText?:string|null;sourceShotIds:string[];skus:Array<{id:string;name:string;roles:string[];rationale?:string}>;preservation?:SourcePreservation|null;dimensions?:FidelityDimension[];reviewStatus?:string|null}

const shotFields=[['visualDescription','画面','Visual'],['shotScale','景别','Shot scale'],['cameraMovement','运镜','Camera movement'],['subjectAction','动作','Action'],['voiceover','旁白','Voiceover'],['onScreenText','字幕','On-screen text'],['sound','声音','Sound'],['narrativePurpose','叙事作用','Purpose'],['transition','衔接','Transition']] as const
const reasonLabels:Record<string,[string,string]>={voiceover_removed_for_visual_storytelling:['视觉叙事：明确不使用口播','Visual storytelling: narration intentionally removed'],overlay_removed_for_visual_storytelling:['视觉叙事：明确不使用画面文字','Visual storytelling: overlay intentionally removed'],sound_removed_for_visual_storytelling:['视觉叙事：明确不使用来源声音','Visual storytelling: source sound intentionally removed'],transition_removed_for_visual_storytelling:['视觉叙事：明确不使用来源转场','Visual storytelling: source transition intentionally removed'],brand_facts:['依据已确认品牌资料调整','Adjusted to confirmed brand facts'],material_feasibility:['依据素材可行性调整','Adjusted for available materials'],platform_style:['依据目标平台风格调整','Adjusted for the target platform']}
const dimensionLabels:Record<string,[string,string]>={hook:['开场吸引力','Opening hook'],narrative_order:['叙事顺序','Narrative order'],selling_point_position:['卖点位置','Selling-point placement'],continuity:['镜头衔接','Continuity'],cta:['行动引导','Call to action'],diversity:['镜头差异','Scene diversity']}
const preservationLabels:Record<string,[string,string]>={preserved:['保留','Preserved'],adapted:['已调整','Adjusted'],not_applicable:['不适用','Not applicable']}
const issueLabel=(issue:string,t:(zh:string,en:string)=>string)=>{
 if(issue.startsWith('source_opening_hook_missing'))return t('未保留原片的开场吸引方式','The source opening hook was not retained')
 if(issue.startsWith('source_shot_order_changed'))return t('原分镜顺序发生变化','The source shot order changed')
 if(issue.startsWith('selling_point_position_changed'))return t('卖点出现位置发生变化','The selling point moved to another point')
 if(issue.startsWith('source_cta_missing'))return t('原片的行动引导未保留','The source call to action was not retained')
 if(issue.startsWith('source_continuity_missing'))return t('来源中的衔接要求未保留','A source continuity requirement was not retained')
 if(issue.startsWith('distinct_source_beats_collapsed'))return t('不同分镜被处理得过于相似','Distinct source beats became too similar')
 if(issue.startsWith('complete_source_required'))return t('来源资料不足，无法完成此项复核','Source evidence is insufficient for this review')
 if(issue.startsWith('structured_model_review_required'))return t('此项仍待复核','This dimension still needs review')
 return issue
}

function EvidenceGap({t}:{t:(zh:string,en:string)=>string}){return <div className="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm leading-6 text-amber-900"><p className="flex items-center gap-2 font-semibold"><AlertTriangle className="h-4 w-4"/>{t('来源证据不足','Insufficient source evidence')}</p><p className="mt-1">{t('当前品牌工作区没有可核对的完整来源记录。缺失内容保持待确认，不根据脚本反推。','This brand workspace does not contain a complete source record to verify. Missing details remain unconfirmed and are never inferred from the script.')}</p></div>}

function Comparison({source,shotId,adapted,english=false}:{source:CreativeSource;shotId:string;adapted:SourceComparisonShot;english?:boolean}){
 const t=(zh:string,en:string)=>english?en:zh,sourceShot=source.timeline.find(shot=>shot.id===shotId)
 const roles=[['hookRole',t('开场作用','Hook role')],['narrativeRole',t('叙事作用','Narrative role')],['pacingRole',t('节奏作用','Pacing role')]] as const
 const failed=(adapted.dimensions||[]).filter(d=>d.status==='failed')
 return <div className="space-y-4">
  <section aria-labelledby="viral-video-title" className="rounded-2xl border border-slate-200 bg-slate-950 p-3 text-white"><div className="mb-3 flex items-center justify-between gap-3"><div><p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-violet-300">{source.platform||t('来源平台待确认','Source platform unconfirmed')}</p><h3 id="viral-video-title" className="mt-1 flex items-center gap-2 text-sm font-semibold"><Film className="h-4 w-4"/>{t('爆款原视频','Original viral video')}</h3></div><p className="max-w-[50%] truncate text-xs text-slate-300">{source.title||t('标题待确认','Title unconfirmed')}</p></div>{source.originalVideoUrl?<video controls preload="metadata" src={source.originalVideoUrl} aria-label={t('爆款原视频','Original viral video')} className="max-h-[38dvh] w-full rounded-xl bg-black object-contain"/>:<EvidenceGap t={t}/>}</section>
  {!sourceShot?<EvidenceGap t={t}/>:<div className="grid min-w-0 gap-3 lg:grid-cols-2">
   <article className="min-w-0 rounded-2xl border border-slate-200 bg-slate-50 p-4"><p className="flex items-center gap-2 text-xs font-semibold text-slate-500"><Link2 className="h-4 w-4 text-violet-600"/>{t('原分镜','Original shot')}</p><p className="mt-2 font-mono text-xs text-slate-500">{t('镜头','Shot')} {sourceShot.order} · {sourceShot.startSec??'—'}–{sourceShot.endSec??'—'}s</p><dl className="mt-3 space-y-2">{shotFields.map(([field,zh,en])=><div key={field}><dt className="text-[11px] font-semibold text-slate-500">{t(zh,en)}</dt><dd className="whitespace-pre-wrap break-words text-sm leading-6 text-slate-800">{typeof sourceShot[field]==='string'&&sourceShot[field]?sourceShot[field] as string:t('待确认','Unconfirmed')}</dd></div>)}</dl></article>
   <article className="min-w-0 rounded-2xl border border-violet-200 bg-violet-50/60 p-4"><p className="flex items-center gap-2 text-xs font-semibold text-violet-700"><Film className="h-4 w-4"/>{t('品牌新分镜','Adapted brand shot')}</p><p className="mt-2 text-sm font-semibold text-slate-900">{adapted.title||t('品牌分镜','Brand shot')}</p>{adapted.clipUrl?<video controls preload="metadata" src={adapted.clipUrl} aria-label={t('品牌新分镜视频','Adapted brand shot video')} className="mt-3 max-h-56 w-full rounded-xl bg-slate-950 object-contain"/>:<p className="mt-3 rounded-lg bg-white p-3 text-xs text-slate-500">{t('该分镜暂无可核对的视频片段。','No verifiable rendered clip is available for this shot.')}</p>}<dl className="mt-3 space-y-2"><div><dt className="text-[11px] font-semibold text-slate-500">{t('画面说明','Visual direction')}</dt><dd className="whitespace-pre-wrap break-words text-sm leading-6">{adapted.prompt||t('待确认','Unconfirmed')}</dd></div><div><dt className="text-[11px] font-semibold text-slate-500">{t('口播与逐字字幕','Voice and verbatim captions')}</dt><dd className="whitespace-pre-wrap break-words text-sm leading-6">{adapted.spokenText||t('无口播','No narration')}</dd></div><div><dt className="text-[11px] font-semibold text-slate-500">{t('画面文字','On-screen copy')}</dt><dd className="whitespace-pre-wrap break-words text-sm leading-6">{adapted.overlayText||t('无画面文字','No on-screen copy')}</dd></div></dl></article>
  </div>}
  <div className="grid min-w-0 gap-3 md:grid-cols-2">
   <section className="rounded-2xl border border-slate-200 bg-white p-4"><h3 className="flex items-center gap-2 text-sm font-semibold"><PackageCheck className="h-4 w-4 text-violet-600"/>{t('SKU 映射','SKU mapping')}</h3>{adapted.skus.length?<ul className="mt-3 space-y-3">{adapted.skus.map(sku=><li key={sku.id} className="rounded-xl bg-slate-50 p-3"><p className="text-sm font-semibold">{sku.name}</p><p className="mt-1 text-xs text-slate-500">{sku.roles.join(' / ')||t('角色待确认','Role unconfirmed')}</p>{sku.rationale&&<p className="mt-2 text-xs leading-5 text-slate-600">{sku.rationale}</p>}</li>)}</ul>:<p className="mt-3 text-sm text-slate-500">{t('此分镜的 SKU 对应关系待确认。','SKU mapping for this shot is unconfirmed.')}</p>}</section>
   <section className="rounded-2xl border border-slate-200 bg-white p-4"><h3 className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck className="h-4 w-4 text-violet-600"/>{t('保留与调整原因','Preservation and adjustment reasons')}</h3>{adapted.preservation?<><dl className="mt-3 grid grid-cols-3 gap-2">{roles.map(([key,label])=><div key={key} className="rounded-lg bg-slate-50 p-2"><dt className="text-[11px] text-slate-500">{label}</dt><dd className="mt-1 text-xs font-semibold">{preservationLabels[adapted.preservation?.[key]||'']?.[english?1:0]||t('待确认','Unconfirmed')}</dd></div>)}</dl><ul className="mt-3 space-y-2 text-sm">{adapted.preservation.changeReasons?.length?adapted.preservation.changeReasons.map(reason=><li key={reason}>{reasonLabels[reason]?.[english?1:0]||t('调整原因待确认','Adjustment reason unconfirmed')}</li>):<li className="text-slate-500">{t('未记录调整原因。','No adjustment reason recorded.')}</li>}</ul></>:<p className="mt-3 text-sm text-slate-500">{t('保留与调整记录待确认。','Preservation and adjustment evidence is unconfirmed.')}</p>}</section>
  </div>
  <section className="rounded-2xl border border-slate-200 bg-white p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="text-sm font-semibold">{t('质量复核','Quality review')}</h3><p className="mt-1 text-xs text-slate-500">{t('复核意见，不代表最终事实。','Review notes, not final facts.')}</p></div><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${failed.length?'bg-amber-100 text-amber-900':'bg-slate-100 text-slate-600'}`}>{failed.length?t('需要人工检查','Needs human review'):adapted.reviewStatus==='passed'?t('复核通过','Review passed'):t('待确认','Unconfirmed')}</span></div>{failed.length?<ul className="mt-3 space-y-3">{failed.map(dimension=><li key={dimension.key} className="border-l-2 border-amber-400 pl-3"><p className="text-sm font-semibold">{dimensionLabels[dimension.key]?.[english?1:0]||t('其他复核项','Other review area')}</p><ul className="mt-1 space-y-1 text-sm leading-6 text-slate-700">{dimension.issues.map((issue,index)=><li key={`${issue}:${index}`}>{issueLabel(issue,t)}</li>)}</ul></li>)}</ul>:<p className="mt-3 text-sm text-slate-500">{t('当前分镜没有可验证的失败项。','No verified failed dimension is bound to this shot.')}</p>}</section>
 </div>
}

export default function CreativeSourceComparison({source,error,shotId,onShot,english=false,comparison,embedded=false}:{source:CreativeSource|null;error:string;shotId:string;onShot:(id:string)=>void;english?:boolean;comparison?:SourceComparisonShot|null;embedded?:boolean}){
 const t=(zh:string,en:string)=>english?en:zh
 if(comparison)return source&&source.evidenceStatus==='full_source'?<Comparison source={source} shotId={shotId} adapted={comparison} english={english}/>:<EvidenceGap t={t}/>
 return <section id="creative-source" tabIndex={-1} className={`${embedded?'':'rounded-xl border border-slate-200 bg-white p-4'} min-w-0 focus-visible:outline-violet-600`}><h3 className="font-semibold">{t('原创意参考','Original reference')}</h3>
 {!source?<p role="status" className="mt-3 text-sm text-slate-500">{error||t('正在读取原创意…','Loading original idea…')}</p>:<><div className="mt-3 flex flex-wrap items-center gap-2"><p className="text-base font-semibold">{source.title||t('原创意参考','Original reference')}</p>{source.platform&&<span className="rounded-full bg-slate-100 px-3 py-1 text-xs capitalize text-slate-600">{source.platform}</span>}</div><div className="my-3 flex flex-wrap gap-3 text-sm"><a className="rounded font-semibold text-violet-700 underline focus-visible:outline-violet-600" href={source.internalDetailPath}>{t('查看原创意详情','Open source detail')}</a>{source.originalPostUrl&&<a href={source.originalPostUrl} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1 rounded text-slate-500 underline focus-visible:outline-violet-600">{t('外部原帖','External original post')}<ExternalLink size={14}/></a>}</div>
 {source.originalVideoUrl?<video controls preload="metadata" src={source.originalVideoUrl} aria-label={t('爆款原视频','Original viral video')} className="max-h-80 w-full rounded-lg bg-slate-900"/>:<p className="text-sm text-slate-500">{t('原视频暂不可读取，请查看原帖或稍后重试。','Original video unavailable. Open the original post or retry later.')}</p>}
 {source.evidenceStatus!=='full_source'&&<p className="my-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">{source.evidenceStatus==='partial_source'?t('原始资料不完整，缺失内容待确认。','Source evidence is incomplete; missing details need confirmation.'):t('暂无可验证的原分镜，不能按爆款复刻。','No verified source shots are available for adaptation.')}</p>}
 <p className="mt-4 whitespace-pre-wrap break-words text-sm leading-7">{source.sourceEvidence.originalText}</p><nav aria-label={t('分镜轨道','Shot track')} className="my-4 flex flex-wrap gap-2">{source.timeline.map(s=><button key={s.id} type="button" aria-pressed={shotId===s.id} onClick={()=>onShot(s.id)} className={`min-h-11 max-w-full break-all rounded-lg border px-3 py-2 font-mono text-xs focus-visible:outline focus-visible:outline-2 focus-visible:outline-violet-600 ${shotId===s.id?'border-violet-600 bg-violet-50 text-violet-700':'border-slate-200'}`}>{t('镜头','Shot')} {s.order}</button>)}</nav>
 {source.timeline.map(s=><article key={s.id} data-shot-id={s.id} className={`mb-3 min-w-0 rounded-lg border-l-2 p-3 ${shotId===s.id?'border-violet-600 bg-violet-50':'border-slate-200'}`}><h4 className="break-all font-mono text-xs">{t('镜头','Shot')} {s.order} · {s.startSec??'—'}–{s.endSec??'—'}s</h4><dl className="mt-2 space-y-2">{shotFields.map(([field,zh,en])=><div key={field}><dt className="text-xs text-slate-500">{t(zh,en)}</dt><dd className="whitespace-pre-wrap break-words text-sm leading-6">{typeof s[field]==='string'?s[field] as string:t('待确认','Unconfirmed')}</dd></div>)}</dl></article>)}</>}
 </section>
}
